#!/usr/bin/env python3
"""Generates the plug-in's Parameters.lua, the Mac app's
ParameterCatalogData.swift and the Windows app's ParameterCatalogData.g.cs
from Shared/parameters.json (the single source of truth). Run from anywhere:
python3 Scripts/generate-parameters.py [--check]
--check exits 1 when the generated files are out of date (used by tests)."""
import json, pathlib, sys

root = pathlib.Path(__file__).resolve().parent.parent
catalog = json.loads((root / "Shared/parameters.json").read_text())
params = catalog["parameters"]

def check(p):
    """Step rules both sides rely on. The default steps sit inside the range
    offered for custom steps, and the large default step fits in one request.
    In Library every request is its own catalog transaction (one undo step),
    so there even the largest custom step must fit in one request."""
    where = f"{p.get('scope')}:{p.get('id')}"
    missing = [k for k in ("id", "label", "section", "scope", "unit", "normal", "coarse",
                           "maxDelta", "stepMin", "stepMax") if k not in p]
    if missing:
        return f"{where}: missing {', '.join(missing)}"
    if p["scope"] not in ("develop", "library"):
        return f"{where}: unknown scope"
    if not 0 < p["stepMin"] <= p["stepMax"]:
        return f"{where}: stepMin must be above 0 and at most stepMax"
    for name in ("normal", "coarse"):
        if not p["stepMin"] <= p[name] <= p["stepMax"]:
            return f"{where}: {name} {p[name]} is outside {p['stepMin']}–{p['stepMax']}"
    if p["coarse"] > p["maxDelta"]:
        return f"{where}: coarse {p['coarse']} is above maxDelta {p['maxDelta']}"
    if p["scope"] == "library" and p["stepMax"] > p["maxDelta"]:
        return f"{where}: stepMax {p['stepMax']} is above maxDelta {p['maxDelta']}"
    return None

problems = [problem for problem in map(check, params) if problem]
keys = [(p.get("scope"), p.get("id")) for p in params]
problems += [f"{scope}:{id} appears more than once" for scope, id in sorted(set(k for k in keys if keys.count(k) > 1))]
if problems:
    print("Invalid Shared/parameters.json:\n  " + "\n  ".join(problems)); sys.exit(1)

def lua_value(v):
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, (int, float)): return repr(v)
    return '"' + str(v).replace("\\", "\\\\").replace('"', '\\"') + '"'

lua = ["-- GENERATED by Scripts/generate-parameters.py from Shared/parameters.json.",
       "-- Do not edit by hand.", "return {"]
for p in params:
    fields = ", ".join(f"{k} = {lua_value(p[k])}" for k in
                       ["id", "scope", "unit", "maxDelta"] + [k for k in ("wraps", "enumerated", "special", "verify") if k in p])
    lua.append(f"    {{ {fields} }},")
lua.append("}")
lua_text = "\n".join(lua) + "\n"

def swift_str(s): return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'
def swift_num(v): return repr(float(v))
sw = ["// GENERATED by Scripts/generate-parameters.py from Shared/parameters.json.",
      "// Do not edit by hand.", "", "extension ParameterCatalog {",
      "    static let generatedEntries: [ParameterDescriptor] = ["]
for p in params:
    sw.append("        ParameterDescriptor(" + ", ".join([
        f"id: {swift_str(p['id'])}", f"label: {swift_str(p['label'])}", f"section: {swift_str(p['section'])}",
        f"scope: .{p['scope']}", f"unit: {swift_str(p['unit'])}",
        f"normalStep: {swift_num(p['normal'])}", f"coarseStep: {swift_num(p['coarse'])}",
        f"maximumDelta: {swift_num(p['maxDelta'])}",
        f"stepRange: {swift_num(p['stepMin'])}...{swift_num(p['stepMax'])}",
        f"wraps: {'true' if p.get('wraps') else 'false'}",
        f"isEnumerated: {'true' if p.get('enumerated') else 'false'}",
        f"needsVerification: {'true' if p.get('verify') else 'false'}",
    ]) + "),")
sw += ["    ]", "}"]
swift_text = "\n".join(sw) + "\n"

def cs_bool(v): return "true" if v else "false"
cs = ["// GENERATED by Scripts/generate-parameters.py from Shared/parameters.json.",
      "// Do not edit by hand.", "", "namespace Lumerist.Core;", "",
      "public static partial class ParameterCatalog", "{",
      "    internal static readonly ParameterDescriptor[] GeneratedEntries =", "    ["]
for p in params:
    cs.append("        new(" + ", ".join([
        swift_str(p["id"]), swift_str(p["label"]), swift_str(p["section"]),
        "ParameterScope." + p["scope"].capitalize(), swift_str(p["unit"]),
        swift_num(p["normal"]), swift_num(p["coarse"]), swift_num(p["maxDelta"]),
        swift_num(p["stepMin"]), swift_num(p["stepMax"]),
        cs_bool(p.get("wraps")), cs_bool(p.get("enumerated")), cs_bool(p.get("verify")),
    ]) + "),")
cs += ["    ];", "}"]
cs_text = "\n".join(cs) + "\n"

targets = {
    root / "Lightroom/Lumerist.lrplugin/Parameters.lua": lua_text,
    root / "Sources/LumeristCore/ParameterCatalogData.swift": swift_text,
    root / "Windows/Lumerist.Core/ParameterCatalogData.g.cs": cs_text,
}
if "--check" in sys.argv:
    stale = [str(p) for p, t in targets.items() if not p.exists() or p.read_text() != t]
    if stale:
        print("Out of date: " + ", ".join(stale)); sys.exit(1)
    print("Generated parameter files are up to date."); sys.exit(0)
for path, text in targets.items():
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)
    print("Wrote", path.relative_to(root))
